    TContext = unknown>(queryClient: QueryClient, options?: { mutation?:CreateMutationOptions<Awaited<ReturnType<typeof deleteTask>>, TError,DeleteTaskMutationVariables, TContext>, skipInvalidation?: boolean, request?: SecondParameter<typeof apiFetch>}
): CreateMutationOptions<Awaited<ReturnType<typeof deleteTask>>, TError,DeleteTaskMutationVariables, TContext> => {

const mutationKey = getDeleteTaskMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof deleteTask>>, DeleteTaskMutationVariables> = (props) => {
          const {id} = props ?? {};

          return  deleteTask(id,requestOptions)
        }

  const onSuccess = (data: Awaited<ReturnType<typeof deleteTask>>, variables: DeleteTaskMutationVariables, onMutateResult: TContext, context: MutationFunctionContext) => {
        if (!options?.skipInvalidation) {
        queryClient.invalidateQueries({ queryKey: getListTasksQueryKey() });
        }
        mutationOptions?.onSuccess?.(data, variables, onMutateResult, context);
      };




  return  { ...mutationOptions, mutationFn, onSuccess }}

    export type DeleteTaskMutationResult = NonNullable<Awaited<ReturnType<typeof deleteTask>>>

    export type DeleteTaskMutationError = string
    export type DeleteTaskMutationVariables = {id: string}

    export const createDeleteTask = <TError = string,
    TContext = unknown>(options?: () => { mutation?:CreateMutationOptions<Awaited<ReturnType<typeof deleteTask>>, TError,DeleteTaskMutationVariables, TContext>, skipInvalidation?: boolean, request?: SecondParameter<typeof apiFetch>}
 , queryClient?: () => QueryClient): CreateMutationResult<
        Awaited<ReturnType<typeof deleteTask>>,
        TError,
        DeleteTaskMutationVariables,
        TContext
      > => {
      const backupQueryClient = useQueryClient(queryClient?.());
      return createMutation(() => ({ ...getDeleteTaskMutationOptions(backupQueryClient, options?.()) }), queryClient);
    }

export type toggleTaskResponse200 = {
  data: ToggleResult
  status: 200
}

export type toggleTaskResponse404 = {
  data: string
  status: 404
}

export type toggleTaskResponseSuccess = (toggleTaskResponse200) & {
  headers: Headers;
};
export type toggleTaskResponseError = (toggleTaskResponse404) & {
  headers: Headers;
};

export type toggleTaskResponse = (toggleTaskResponseSuccess | toggleTaskResponseError)

export const getToggleTaskUrl = (id: string,) => {




  return `/api/tasks/${id}/toggle`
}

export const toggleTask = async (id: string,
    toggleInput: ToggleInput, options?: Parameters<typeof apiFetch>[1]): Promise<toggleTaskResponse> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return apiFetch<toggleTaskResponse>(getToggleTaskUrl(id),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(toggleInput)
  }
);}





export const getToggleTaskMutationKey = () => ['toggleTask'] as const;

export const getToggleTaskMutationOptions = <TError = string,
    TContext = unknown>(queryClient: QueryClient, options?: { mutation?:CreateMutationOptions<Awaited<ReturnType<typeof toggleTask>>, TError,ToggleTaskMutationVariables, TContext>, skipInvalidation?: boolean, request?: SecondParameter<typeof apiFetch>}
): CreateMutationOptions<Awaited<ReturnType<typeof toggleTask>>, TError,ToggleTaskMutationVariables, TContext> => {

const mutationKey = getToggleTaskMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof toggleTask>>, ToggleTaskMutationVariables> = (props) => {
          const {id,data} = props ?? {};

          return  toggleTask(id,data,requestOptions)
        }

  const onSuccess = (data: Awaited<ReturnType<typeof toggleTask>>, variables: ToggleTaskMutationVariables, onMutateResult: TContext, context: MutationFunctionContext) => {
        if (!options?.skipInvalidation) {
        queryClient.invalidateQueries({ queryKey: getListTasksQueryKey() });
        }
        mutationOptions?.onSuccess?.(data, variables, onMutateResult, context);
      };




  return  { ...mutationOptions, mutationFn, onSuccess }}

    export type ToggleTaskMutationResult = NonNullable<Awaited<ReturnType<typeof toggleTask>>>
    export type ToggleTaskMutationBody = ToggleInput
    export type ToggleTaskMutationError = string
    export type ToggleTaskMutationVariables = {id: string;data: ToggleInput}

    export const createToggleTask = <TError = string,
    TContext = unknown>(options?: () => { mutation?:CreateMutationOptions<Awaited<ReturnType<typeof toggleTask>>, TError,ToggleTaskMutationVariables, TContext>, skipInvalidation?: boolean, request?: SecondParameter<typeof apiFetch>}
 , queryClient?: () => QueryClient): CreateMutationResult<
        Awaited<ReturnType<typeof toggleTask>>,
        TError,
        ToggleTaskMutationVariables,
        TContext
      > => {
      const backupQueryClient = useQueryClient(queryClient?.());
      return createMutation(() => ({ ...getToggleTaskMutationOptions(backupQueryClient, options?.()) }), queryClient);
    }

export type healthResponse200 = {
  data: void
  status: 200
}

export type healthResponse503 = {
  data: string
  status: 503
}

export type healthResponseSuccess = (healthResponse200) & {
  headers: Headers;
};
export type healthResponseError = (healthResponse503) & {
  headers: Headers;
};

export type healthResponse = (healthResponseSuccess | healthResponseError)

export const getHealthUrl = () => {




  return `/health`
}

export const health = async ( options?: Parameters<typeof apiFetch>[1]): Promise<healthResponse> => {

  return apiFetch<healthResponse>(getHealthUrl(),
  {
    ...options,
    method: 'GET'


  }
);}





export const getHealthQueryKey = () => {
    return [
    `/health`
    ] as const;
    }


export const getHealthQueryOptions = <TData = Awaited<ReturnType<typeof health>>, TError = string>( options?: { query?:Partial<CreateQueryOptions<Awaited<ReturnType<typeof health>>, TError, TData>>, request?: SecondParameter<typeof apiFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getHealthQueryKey();



    const queryFn: QueryFunction<Awaited<ReturnType<typeof health>>> = ({ signal }) => health({ signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as CreateQueryOptions<Awaited<ReturnType<typeof health>>, TError, TData> & { queryKey: DataTag<QueryKey, TData, TError> }
}

export type HealthQueryResult = NonNullable<Awaited<ReturnType<typeof health>>>
export type HealthQueryError = string



export function createHealth<TData = Awaited<ReturnType<typeof health>>, TError = string>(
  options?: () => { query?:Partial<CreateQueryOptions<Awaited<ReturnType<typeof health>>, TError, TData>>, request?: SecondParameter<typeof apiFetch>}
 , queryClient?: () => QueryClient
 ): CreateQueryResult<TData, TError> & { queryKey: DataTag<QueryKey, TData, TError> } {



  const query = createQuery(() => getHealthQueryOptions(options?.()), queryClient) as CreateQueryResult<TData, TError> & { queryKey: DataTag<QueryKey, TData, TError> };

  return query
}


/**
 * @summary Invalidates the {@link createHealth} query
 */
export const invalidateHealth = async (
 queryClient: QueryClient,  options?: InvalidateOptions
  ): Promise<QueryClient> => {

  await queryClient.invalidateQueries({ queryKey: getHealthQueryKey() }, options);

  return queryClient;
}
